lib = '''"""Reusable helpers for band/block lattice ARC tasks (n = L blocks of L with 1-cell pitch separators)."""

def dims(g):
    L = 3 if len(g) == 11 else 4  # lattice size inferred from grid height
    return L, L + 1

def blocks_of(g):
    """Split grid into (L x L) blocks of size L with pitch L+1; returns dict {(b,k): 2d block}."""
    L, p = dims(g)
    return {(b, k): [[g[p*b+r][p*k+c] for c in range(L)] for r in range(L)]
            for b in range(L) for k in range(L)}

def wall_band(g):
    """Return ('r'|'c', index) of the full band of 3s, or None."""
    L, p = dims(g)
    for i in range(L):
        if all(v == 3 for v in g[p*i]):
            return ('r', i)
    for i in range(L):
        if all(g[r][p*i] == 3 for r in range(len(g))):
            return ('c', i)
    return None

def classify(g):
    """Return (shape_block_positions, empty_block_positions) as sorted lists."""
    bl = blocks_of(g)
    shapes = sorted(pos for pos, blk in bl.items() if any(2 in row for row in blk))
    empties = sorted(pos for pos, blk in bl.items()
                     if not any(2 in row for row in blk) and not all(v == 3 for row in blk for v in row))
    return shapes, empties

def first_shape(g):
    """Return the first (reading-order) shape block as a 2d list."""
    L, p = dims(g)
    for b in range(L):
        for k in range(L):
            blk = [[g[p*b+r][p*k+c] for c in range(L)] for r in range(L)]
            if any(2 in row for row in blk):
                return blk
    return None

def clear_wall(out, g):
    """Zero out the wall band in out (wall detected on g)."""
    L, p = dims(g)
    wb = wall_band(g)
    if wb is None:
        return out
    kind, band = wb
    if kind == 'r':
        for r in range(p*band, p*band + L):
            out[r] = [0] * len(g)
    else:
        for r in range(len(g)):
            for c in range(p*band, p*band + L):
                out[r][c] = 0
    return out

def stamp(out, S, pos):
    """Stamp shape S at block pos and mark 8 at the block's anchor cell (p*b+b, p*k+k)."""
    L, p = dims(out)
    b, k = pos
    for r in range(L):
        for c in range(L):
            out[p*b+r][p*k+c] = S[r][c]
    out[p*b+b][p*k+k] = 8
    return out

def self_copy_positions(S, empties):
    """Positions where the shape should be copied: empty blocks whose (b,k) matches a 2-cell of S."""
    L = len(S)
    return [(b, k) for (b, k) in empties if 0 <= b < L and 0 <= k < L and S[b][k] == 2]
